"""
Relays a legacy show*Toast message to system.kanoa.toast.show.
payload is either a message string or a dict with 'message' plus any
system.kanoa.toast.show keys (title, id, position, autoClose, ...).
Legacy styling keys (bgColor, fgColor, icon) are ignored.
"""
if not isinstance(payload, dict):
	payload = {'message': payload}

message = payload.get('message')
if not message:
	return

params = {'message': message, 'type': payload.get('type') or toastType}
for key in ('id', 'title', 'position', 'autoClose', 'closeButton', 'pauseOnHover', 'draggable', 'loading', 'animate'):
	if payload.get(key) is not None:
		params[key] = payload[key]

try:
	system.kanoa.toast.show(params)
except:
	system.util.getLogger('kanoa.toast').warn('Failed to show toast: %s' % (params,))
